```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Arrange: The stage is set for our epic
const mockCart = {
  items: [{ id: '1', name: 'Lyre of Apollo', price: 299.99 }],
  total: 299.99,
  clearCart: vi.fn(),
};

const mockProcessPayment = vi.fn();

const renderCheckout = (props = {}) => {
  return render(
    <CartProvider value={mockCart}>
      <PaymentProvider value={{ processPayment: mockProcessPayment }}>
        <Checkout {...props} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout: The Epic Journey', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'OLYMPUS-123' });
  });

  // HAPPY PATH - The Hero's Complete Journey
  it('completes full checkout flow from shipping to confirmation', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    renderCheckout({ onComplete });

    // Act: Shipping step
    await user.type(screen.getByLabelText(/street address/i), '123 Mount Olympus');
    await user.type(screen.getByLabelText(/city/i), 'Athens');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '90210');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Zeus Thunderer');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review and place order
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Assert: Victory is ours
    await waitFor(() => {
      expect(screen.getByRole('status')).toHaveTextContent('OLYMPUS-123');
    });
    expect(onComplete).toHaveBeenCalledWith('OLYMPUS-123');
  });

  // VALIDATION - The Guardian Tests
  describe('Form Validation', () => {
    it('displays error when ZIP code format is invalid', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByLabelText(/zip code/i), 'INVALID');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code/i);
      expect(screen.getByLabelText(/zip code/i)).toHaveAttribute('aria-invalid', 'true');
    });
  });

  // EDGE CASES - The Odyssey of Errors
  it('shows empty cart message when no items exist', () => {
    render(<Checkout />, { wrapper: EmptyCartProvider });

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });

  // LOADING STATE - The Waiting of Penelope
  it('disables buttons and shows loading during payment processing', async () => {
    mockProcessPayment.mockImplementation(() => new Promise(() => {}));
    // ...proceed to review step...

    expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
  });

  // ACCESSIBILITY - Worthy of All Mortals
  it('has no accessibility violations', async () => {
    const { container } = renderCheckout();
    expect(await axe(container)).toHaveNoViolations();
  });
});
